'use strict';

function replaceOwned(root, segments, replacement) {
  if (!Array.isArray(segments) || segments.length === 0 || segments.some(part => typeof part !== 'string')) {
    throw new TypeError('invalid path');
  }

  function visit(current, depth) {
    if (current === null || typeof current !== 'object') return { changed: false, value: current };
    const part = segments[depth];
    if (Array.isArray(current) && !/^(0|[1-9]\d*)$/.test(part)) return { changed: false, value: current };
    if (!(part in current)) return { changed: false, value: current };

    if (depth === segments.length - 1) {
      const clone = Array.isArray(current) ? current.slice() : { ...current };
      clone[part] = replacement;
      return { changed: true, value: clone };
    }

    const child = visit(current[part], depth + 1);
    if (!child.changed) return { changed: false, value: current };
    const clone = Array.isArray(current) ? current.slice() : { ...current };
    clone[part] = child.value;
    return { changed: true, value: clone };
  }

  return visit(root, 0);
}

module.exports = { replaceOwned };

