'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['replaceOwned']);
const { replaceOwned } = api;

const leaf = { old: true };
const untouched = { stable: true };
const root = {
  left: { items: [leaf, { value: 2 }], untouched },
  right: untouched
};
const segments = ['left', 'items', '0'];
const replacement = { fresh: true };
const result = replaceOwned(root, segments, replacement);
assert.strictEqual(result.changed, true);
assert.notStrictEqual(result.value, root);
assert.notStrictEqual(result.value.left, root.left);
assert.notStrictEqual(result.value.left.items, root.left.items);
assert.strictEqual(result.value.left.items[0], replacement);
assert.strictEqual(result.value.left.items[1], root.left.items[1]);
assert.strictEqual(result.value.left.untouched, untouched);
assert.strictEqual(result.value.right, untouched);
assert.strictEqual(root.left.items[0], leaf);
assert.deepStrictEqual(segments, ['left', 'items', '0']);

const direct = replaceOwned({ key: 1, other: 2 }, ['key'], 9);
assert.deepStrictEqual(direct, { changed: true, value: { key: 9, other: 2 } });
const arrayRoot = [1, { x: 2 }];
const arrayResult = replaceOwned(arrayRoot, ['1', 'x'], 3);
assert.strictEqual(arrayResult.changed, true);
assert.deepStrictEqual(arrayResult.value, [1, { x: 3 }]);
assert.notStrictEqual(arrayResult.value, arrayRoot);
assert.notStrictEqual(arrayResult.value[1], arrayRoot[1]);
assert.deepStrictEqual(arrayRoot, [1, { x: 2 }]);

for (const badSegments of [null, 'x', [], [0], ['x', 1]]) {
  assert.throws(() => replaceOwned(root, badSegments, 1), TypeError);
}
for (const badPath of [['missing'], ['left', 'missing'], ['left', 'items', '00'], ['left', 'items', '-1'], ['left', 'items', '2'], ['left', 'items', 'length'], ['left', 'items', '0', 'missing']]) {
  const failed = replaceOwned(root, badPath, 1);
  assert.deepStrictEqual(failed, { changed: false, value: root });
  assert.strictEqual(failed.value, root);
}
const primitiveFailure = replaceOwned(7, ['x'], 1);
assert.deepStrictEqual(primitiveFailure, { changed: false, value: 7 });
assert.deepStrictEqual(replaceOwned({}, ['x'], 1), { changed: false, value: {} });
assert.deepStrictEqual(replaceOwned([], ['0'], 1), { changed: false, value: [] });

const inheritedRoot = Object.create({ inherited: { x: 1 } });
inheritedRoot.own = 2;
const inheritedFailure = replaceOwned(inheritedRoot, ['inherited', 'x'], 3);
assert.strictEqual(inheritedFailure.changed, false);
assert.strictEqual(inheritedFailure.value, inheritedRoot);

